<section class="card filter-card" aria-label="Filter metode pembayaran"><form class="module-filters module-filters--payment" method="GET" action="{{ route('payment-methods.index') }}">
    <div class="form-group"><label class="form-label" for="payment-search">Pencarian</label><input class="form-control" id="payment-search" name="search" type="search" maxlength="100" value="{{ $search }}" placeholder="Kode atau nama"></div>
    <div class="form-group"><label class="form-label" for="payment-status">Status</label><select class="form-control" id="payment-status" name="status"><option value="">Semua status</option><option value="active" @selected($status === 'active')>Aktif</option><option value="inactive" @selected($status === 'inactive')>Nonaktif</option></select></div>
    <div class="form-group"><label class="form-label" for="payment-type">Jenis</label><select class="form-control" id="payment-type" name="type"><option value="">Semua jenis</option><option value="cash" @selected($type === 'cash')>Tunai</option><option value="non_cash" @selected($type === 'non_cash')>Non-Tunai</option><option value="other" @selected($type === 'other')>Lainnya</option></select></div>
    <div class="module-filters__actions"><button class="btn btn-primary" type="submit">Terapkan</button><a class="btn btn-secondary" href="{{ route('payment-methods.index') }}">Reset</a></div>
</form></section>
